    r0, r1 = min(r for r, c in mask), max(r for r, c in mask)
    c0, c1 = min(c for r, c in mask), max(c for r, c in mask)

    out = []
    for r in range(r0, r1 + 1):
        best_q, best_score = None, -1
        for q in range(h):
            if r0 <= q <= r1:
                continue
            matches = sum(grid[r][c] == grid[q][c]
                          for c in range(c1 + 1, w)
                          if grid[r][c] != 8 and grid[q][c] != 8)
            count = sum(grid[r][c] != 8 and grid[q][c] != 8
                        for c in range(c1 + 1, w))
            score = matches / count if count else 0
            if score > best_score:
                best_score, best_q = score, q
        out.append([grid[best_q][c] for c in range(c0, c1 + 1)])
    return out
